const payloadJson = process.env.EMAIL_SEND_PAYLOAD_JSON;
if (!recipient || !payloadJson) {
  throw new Error(
    "TEST_RECIPIENT_EMAIL and EMAIL_SEND_PAYLOAD_JSON are required",
  );
}

